# Video scene search: frame feature vectors; scene cuts where consecutive distance spikes.
import math
frames = [[1,1,1],[1.2,1,1],[9,9,9],[9.1,9,9],[2,2,2]]
def dist(a, b):
    return math.sqrt(sum((x-y)**2 for x, y in zip(a, b)))
print("frame-to-frame distances (scene cuts marked *):")
cuts = []
for i in range(1, len(frames)):
    d = dist(frames[i-1], frames[i])
    is_cut = d > 5.0
    if is_cut: cuts.append(i)
    print(f"  {i-1}->{i}: {d:.2f}" + ("  * CUT" if is_cut else ""))
print("scene boundaries at frames:", cuts or "none")

